begin;

-- 章节测试仍使用精选题；扩容后的标准题库不会让学生一次作答 80 题。
alter table public.course_test_questions
  add column if not exists is_chapter_test_item boolean not null default false;

update public.course_test_questions as question
set is_chapter_test_item = true
from public.course_tests as test
where question.test_id = test.id
  and test.course_key = 'hangul-introduction'
  and question.question_key ~ '^c[1-4]-q([1-9]|10)$';

update public.course_test_questions
set difficulty = 'medium'
where difficulty = 'easy';

alter table public.course_test_questions
  drop constraint if exists course_test_questions_difficulty_check;
alter table public.course_test_questions
  add constraint course_test_questions_difficulty_check
  check (difficulty in ('foundation', 'medium', 'hard', 'expert'));

-- 原有 40 道章节测试题补齐 D 选项。
