update public.course_test_questions as question
set options = question.options || jsonb_build_array(d_options.option_d),
    updated_at = now()
from d_options
where question.question_key = d_options.question_key
  and question.test_id in (
    select id from public.course_tests
    where course_key = 'hangul-introduction'
  )
  and jsonb_array_length(question.options) = 3;

