    ('pronunciation-rules-and-reading', 'c4-expert-10', '哪条中间过程能够正确推出“없어요”的标准读音？', '["없어요 → 어버요 → 어버요","없어요 → 업어요 → 어버요","없어요 → 업처요 → 업처요","없어요 → 업서요 → 업써요"]'::jsonb, 3, '없어요 → 업서요 → 업써요 展示了该词所需的连续规则。', '判断流程', 310, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-11', '学习者把“국물”读成 [국물]。漏掉了哪一步？', '["ㅁ 要变成紧音 ㅃ","ㄱ 与 ㅁ 要合成 ㅋ","ㄱ 类收音遇 ㅁ 要鼻音化为 ㅇ","ㄱ 要连到下一元音"]'::jsonb, 2, '正确读音是 [궁물]。', '发音规则', 311, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-12', '学习者把“학교”读成 [하교]。主要问题是什么？', '["错误使用了鼻音化","漏掉了 ㄱ 收音，并且没有把后面的 ㄱ 紧音化","多读了一个 ㅇ","把 ㅛ 读成 ㅗ"]'::jsonb, 1, '학교 应保留前一收音并读作 [학꾜]。', '发音规则', 312, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-13', '学习者把“같이”只做普通连音读成 [가티]。漏掉了什么？', '["ㅌ 与 이 的环境还要发生腭化，变为 ㅊ","ㅌ 要鼻音化为 ㄴ","이 要变成 으","前面要添加 ㄴ"]'::jsonb, 0, '같이 的标准读音是 [가치]。', '发音规则', 313, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-14', '学习者把“좋아요”读成 [조타요]。为什么不对？', '["좋아요 中没有 ㅎ","所有元音都要紧音化","ㅎ 必须变成 ㄴ","ㅎ 后接元音时通常弱化，不能套用 ㅎ＋ㄷ 的激音化"]'::jsonb, 3, '좋다 的后音是 ㄷ，而 좋아요 的后面是元音环境。', '发音规则', 314, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-15', '学习者把“연락”读成 [연낙]。应怎样修正？', '["ㄴ 要完全删除","两个辅音合成 ㅌ","ㄴ＋ㄹ 在该词中流音化为 ㄹ＋ㄹ，读 [열락]","ㄹ 要变成 ㅁ"]'::jsonb, 2, '연락 是常见的流音化词。', '发音规则', 315, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-16', '一词同时有两条边界时，最可靠的操作顺序是什么？', '["把所有收音同时删除","从前到后逐条处理，并让前一步结果进入下一步判断","先猜最终读音，再补规则名称","只处理最后一条边界"]'::jsonb, 1, '连续音变需要保留中间形态。', '判断流程', 316, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-17', '遇到书写收音 ㅅ、ㅊ、ㅌ 后接 ㄴ 时，为什么先归类很重要？', '["它们先归入 ㄷ 类，才能正确应用 ㄷ→ㄴ 的鼻音化","它们都会直接变成 ㄹ","它们都是元音，不能作收音","它们一律连到下一音节"]'::jsonb, 0, '鼻音化依据实际代表音，而不是只看字形。', '判断流程', 317, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-18', '判断 ㅎ 的去向时，最关键的环境信息是什么？', '["单词的中文长度","字母写得大还是小","该词有几个汉字来源","相邻的是辅音还是元音，以及 ㅎ 是否在复收音中"]'::jsonb, 3, 'ㅎ 可激音化、弱化或脱落，必须结合相邻音判断。', '判断流程', 318, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-19', '判断 ㄴ＋ㄹ 是否一律读 ㄹ＋ㄹ，正确态度是什么？', '["任何情况下都读 ㄴ＋ㄴ","只要有 ㄹ 就不发音","不能一律套用；部分汉字词中 ㄹ 会变成 ㄴ","任何情况下都读 ㄹ＋ㄹ"]'::jsonb, 2, '如 심리、독립 等需要按高频例词和具体规则处理。', '判断流程', 319, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb),
    ('pronunciation-rules-and-reading', 'c4-expert-20', '综合测试中看到陌生词，哪套流程最完整？', '["先把辅音变紧→再决定音节","分音节→找收音→看后音→选规则→保留中间过程→合读","先看中文→猜读音→跳过收音","只数元音→全部连音"]'::jsonb, 1, '结构化流程能迁移到未见过的词。', '判断流程', 320, 'expert', '["韩语字母入门","第4章","expert"]'::jsonb)
)
insert into public.course_test_questions (
  test_id, question_key, prompt, options, correct_option, correct_answer,
  explanation, skill, sort_order, question_type, default_points,
  difficulty, tags, status, version, is_chapter_test_item
)
select
  test.id, seed.question_key, seed.prompt, seed.options, seed.correct_option, null,
  seed.explanation, seed.skill, seed.sort_order, 'single_choice', 10,
  seed.difficulty, seed.tags, 'published', 1, false
from seed
join public.course_tests as test on test.slug = seed.test_slug
on conflict (test_id, question_key) do update set
  prompt = excluded.prompt,
  options = excluded.options,
  correct_option = excluded.correct_option,
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  skill = excluded.skill,
  sort_order = excluded.sort_order,
  question_type = excluded.question_type,
  default_points = excluded.default_points,
  difficulty = excluded.difficulty,
  tags = excluded.tags,
  status = excluded.status,
  is_chapter_test_item = excluded.is_chapter_test_item,
  updated_at = now();

-- 平台维护函数支持四档难度；韩语字母入门单选题固定四个选项。
create or replace function public.save_standard_question(
  p_question_id uuid,
  p_test_id uuid,
  p_question_type text,
  p_prompt text,
  p_options jsonb,
  p_correct_option integer,
  p_correct_answer text,
  p_explanation text,
  p_skill text,
  p_default_points numeric,
  p_difficulty text,
  p_tags jsonb,
  p_status text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_question_id uuid;
  v_sort_order integer;
  v_current_test_id uuid;
  v_course_key text;
begin
  if not private.can_manage_standard_question_bank() then
    raise exception '当前账号没有标准题库编辑权限';
  end if;

  p_prompt := btrim(coalesce(p_prompt, ''));
  p_explanation := btrim(coalesce(p_explanation, ''));
  p_skill := btrim(coalesce(p_skill, ''));
  p_correct_answer := nullif(btrim(coalesce(p_correct_answer, '')), '');
  p_options := coalesce(p_options, '[]'::jsonb);
  p_tags := coalesce(p_tags, '[]'::jsonb);

  select course_key into v_course_key
  from public.course_tests
  where id = p_test_id;
  if not found then raise exception '所选课程章节不存在'; end if;
  if p_question_type not in ('short_text', 'long_text', 'single_choice', 'file_link') then raise exception '题型不正确'; end if;
  if char_length(p_prompt) not between 1 and 3000 then raise exception '题目不能为空且不能超过 3000 个字'; end if;
  if char_length(p_explanation) > 3000 then raise exception '解析不能超过 3000 个字'; end if;
  if char_length(p_skill) not between 1 and 80 then raise exception '知识点需要填写 1 至 80 个字'; end if;
  if p_default_points is null or p_default_points <= 0 or p_default_points > 1000 then raise exception '默认分值需要大于 0 且不超过 1000'; end if;
  if p_difficulty not in ('foundation', 'medium', 'hard', 'expert') then raise exception '难度不正确'; end if;
  if p_status not in ('draft', 'published', 'archived') then raise exception '发布状态不正确'; end if;
  if jsonb_typeof(p_tags) <> 'array' then raise exception '标签格式不正确'; end if;

  if p_question_type = 'single_choice' then
    if jsonb_typeof(p_options) <> 'array' or jsonb_array_length(p_options) < 2 then raise exception '选择题至少需要两个选项'; end if;
    if v_course_key = 'hangul-introduction' and jsonb_array_length(p_options) <> 4 then raise exception '韩语字母入门单选题必须正好有四个选项'; end if;
    if p_correct_option is null or p_correct_option < 0 or p_correct_option >= jsonb_array_length(p_options) then raise exception '请选择正确答案'; end if;
    p_correct_answer := null;
  else
    p_options := '[]'::jsonb;
    p_correct_option := null;
  end if;

  if p_question_id is null then
    select coalesce(max(sort_order), 0) + 1 into v_sort_order
    from public.course_test_questions where test_id = p_test_id;
    insert into public.course_test_questions (
      test_id, question_key, prompt, options, correct_option, correct_answer,
      explanation, skill, sort_order, question_type, default_points, difficulty,
      tags, status, version, created_by, updated_by, is_chapter_test_item
    ) values (
      p_test_id, 'bank-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 16),
      p_prompt, p_options, p_correct_option, p_correct_answer, p_explanation,
      p_skill, v_sort_order, p_question_type, p_default_points, p_difficulty,
      p_tags, p_status, 1, auth.uid(), auth.uid(), false
    ) returning id into v_question_id;
  else
    select test_id into v_current_test_id
    from public.course_test_questions where id = p_question_id;
    if not found then raise exception '题目不存在'; end if;
    if v_current_test_id <> p_test_id then
      select coalesce(max(sort_order), 0) + 1 into v_sort_order
      from public.course_test_questions where test_id = p_test_id;
    else
      select sort_order into v_sort_order
      from public.course_test_questions where id = p_question_id;
    end if;
    update public.course_test_questions set
      test_id = p_test_id,
      prompt = p_prompt,
      options = p_options,
      correct_option = p_correct_option,
      correct_answer = p_correct_answer,
      explanation = p_explanation,
      skill = p_skill,
      sort_order = v_sort_order,
      question_type = p_question_type,
      default_points = p_default_points,
      difficulty = p_difficulty,
      tags = p_tags,
      status = p_status,
      version = version + 1,
      updated_by = auth.uid(),
      updated_at = now()
    where id = p_question_id
    returning id into v_question_id;
  end if;
  return v_question_id;
end;
$function$;

revoke all on function public.save_standard_question(
  uuid, uuid, text, text, jsonb, integer, text, text, text,
  numeric, text, jsonb, text
) from public;
grant execute on function public.save_standard_question(
  uuid, uuid, text, text, jsonb, integer, text, text, text,
  numeric, text, jsonb, text
) to authenticated;

-- 学生章节测试只判精选题，题库扩容题仅供平台管理和机构布置。
create or replace function public.submit_course_test(
  p_test_slug text,
  p_answers jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id uuid := private.current_tenant_id();
  v_test public.course_tests%rowtype;
  v_question public.course_test_questions%rowtype;
  v_selected integer;
  v_correct boolean;
  v_correct_count integer := 0;
  v_total_questions integer := 0;
  v_score integer;
  v_passed boolean;
  v_results jsonb := '[]'::jsonb;
  v_dimensions jsonb := '{}'::jsonb;
  v_dimension_scores jsonb := '{}'::jsonb;
  v_dimension_key text;
  v_dimension_value jsonb;
  v_dimension_correct integer;
  v_dimension_total integer;
  v_attempt_id uuid;
begin
  if v_user_id is null or v_tenant_id is null then raise exception '请登录有效的机构账号后再提交测试'; end if;
  if jsonb_typeof(p_answers) is distinct from 'object' then raise exception '答案格式不正确'; end if;
  select * into v_test from public.course_tests where slug = p_test_slug and status = 'published';
  if not found then raise exception '没有找到这份章节测试'; end if;

  select count(*) into v_total_questions
  from public.course_test_questions
  where test_id = v_test.id
    and status = 'published'
    and question_type = 'single_choice'
    and is_chapter_test_item;
  if v_total_questions = 0 or (select count(*) from jsonb_object_keys(p_answers)) <> v_total_questions then
    raise exception '请完成全部题目后再交卷';
  end if;

  for v_question in
    select * from public.course_test_questions
    where test_id = v_test.id
      and status = 'published'
      and question_type = 'single_choice'
      and is_chapter_test_item
    order by sort_order
  loop
    if not (p_answers ? v_question.question_key) then raise exception '请完成全部题目后再交卷'; end if;
    begin
      v_selected := (p_answers ->> v_question.question_key)::integer;
    exception when invalid_text_representation then
      raise exception '有一道题的答案格式不正确';
    end;
    if v_selected < 0 or v_selected >= jsonb_array_length(v_question.options) then raise exception '有一道题的选项不正确'; end if;
    v_correct := v_selected = v_question.correct_option;
    if v_correct then v_correct_count := v_correct_count + 1; end if;
    v_dimension_correct := coalesce((v_dimensions -> v_question.skill ->> 'correct')::integer, 0) + case when v_correct then 1 else 0 end;
    v_dimension_total := coalesce((v_dimensions -> v_question.skill ->> 'total')::integer, 0) + 1;
    v_dimensions := jsonb_set(
      v_dimensions, array[v_question.skill],
      jsonb_build_object('label', coalesce(v_test.skills ->> v_question.skill, v_question.skill), 'correct', v_dimension_correct, 'total', v_dimension_total),
      true
    );
    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'id', v_question.question_key,
      'selectedOption', v_selected,
      'correctOption', v_question.correct_option,
      'correct', v_correct,
      'explanation', v_question.explanation
    ));
  end loop;

  v_score := round((v_correct_count::numeric / v_total_questions::numeric) * 100);
  v_passed := v_score >= v_test.passing_score;
  for v_dimension_key, v_dimension_value in select key, value from jsonb_each(v_dimensions)
  loop
    v_dimension_correct := (v_dimension_value ->> 'correct')::integer;
    v_dimension_total := (v_dimension_value ->> 'total')::integer;
    v_dimension_scores := jsonb_set(
      v_dimension_scores, array[v_dimension_key],
      v_dimension_value || jsonb_build_object('percent', round((v_dimension_correct::numeric / v_dimension_total::numeric) * 100)),
      true
    );
  end loop;

  insert into public.course_test_attempts (
    tenant_id, student_id, test_id, test_slug, test_version, score,
    correct_count, total_questions, passed, answers, dimension_scores
  ) values (
    v_tenant_id, v_user_id, v_test.id, v_test.slug, v_test.version, v_score,
    v_correct_count, v_total_questions, v_passed, p_answers, v_dimension_scores
  ) returning id into v_attempt_id;

  return jsonb_build_object(
    'attemptId', v_attempt_id, 'score', v_score, 'correctCount', v_correct_count,
    'totalQuestions', v_total_questions, 'passed', v_passed,
    'dimensionScores', v_dimension_scores, 'questions', v_results
  );
end;
$function$;

revoke all on function public.submit_course_test(text, jsonb) from public;
grant execute on function public.submit_course_test(text, jsonb) to authenticated;

create index if not exists course_test_questions_chapter_test_idx
  on public.course_test_questions(test_id, sort_order)
  where status = 'published' and question_type = 'single_choice' and is_chapter_test_item;

comment on column public.course_test_questions.is_chapter_test_item is
  '是否属于学生章节测试精选题；false 仍可在标准题库中用于作业与考试。';

do $verification$
declare
  v_bad_group_count integer;
  v_bad_option_count integer;
  v_chapter_test_count integer;
  v_total_question_count integer;
  v_duplicate_prompt_count integer;
begin
  select count(*) into v_total_question_count
  from public.course_test_questions as question
  join public.course_tests as test on test.id = question.test_id
  where test.course_key = 'hangul-introduction'
    and question.status = 'published'
    and question.question_type = 'single_choice';
  if v_total_question_count <> 320 then raise exception '韩语题库总数校验失败：%', v_total_question_count; end if;

  select count(*) into v_bad_group_count
  from (
    select test.id, difficulty, count(*) as question_count
    from public.course_tests as test
    join public.course_test_questions as question on question.test_id = test.id
    where test.course_key = 'hangul-introduction'
      and question.status = 'published'
      and question.question_type = 'single_choice'
    group by test.id, difficulty
    having count(*) <> 20
  ) as invalid_groups;
  if v_bad_group_count <> 0 then raise exception '韩语题库章节/难度数量校验失败'; end if;

  select count(*) into v_bad_option_count
  from public.course_test_questions as question
  join public.course_tests as test on test.id = question.test_id
  where test.course_key = 'hangul-introduction'
    and question.question_type = 'single_choice'
    and jsonb_array_length(question.options) <> 4;
  if v_bad_option_count <> 0 then raise exception '韩语题库四选项校验失败'; end if;

  select count(*) into v_duplicate_prompt_count
  from (
    select question.test_id, question.prompt
    from public.course_test_questions as question
    join public.course_tests as test on test.id = question.test_id
    where test.course_key = 'hangul-introduction'
      and question.status = 'published'
      and question.question_type = 'single_choice'
    group by question.test_id, question.prompt
    having count(*) > 1
  ) as duplicate_prompts;
  if v_duplicate_prompt_count <> 0 then raise exception '韩语题库题干重复校验失败'; end if;

  select count(*) into v_chapter_test_count
  from public.course_test_questions as question
  join public.course_tests as test on test.id = question.test_id
  where test.course_key = 'hangul-introduction'
    and question.is_chapter_test_item;
  if v_chapter_test_count <> 40 then raise exception '章节测试精选题数量校验失败'; end if;
end;
$verification$;

commit;
